  describe("배열", () => {
    it("배열 생성", () => {
      const { output } = exec(
        `var arr = [1, 2, 3]
println(str(length(arr)))`
      );
      expect(output).toEqual(["3"]);
    });

    it("배열 인덱싱", () => {
      const { output } = exec(
        `var arr = ["a", "b", "c"]
println(arr[1])`
      );
      expect(output).toEqual(["b"]);
    });
  });

  describe("메모리 관리 - 스택 & 로컬 변수", () => {
    it("여러 지역 변수 동시 관리", () => {
      const { output } = exec(
        `var a = 1
var b = 2
var c = 3
var d = 4
var e = 5
println(str(a + b + c + d + e))`
      );
      expect(output).toEqual(["15"]);
    });

    it("변수 재사용 (가비지 X)", () => {
      const { output } = exec(
        `var x = 10
x = 20
x = 30
x = 40
println(str(x))`
      );
      expect(output).toEqual(["40"]);
    });

    it("깊은 스택 (100+ 푸시)", () => {
      let code = "var sum: i32 = 0\n";
      for (let i = 0; i < 50; i++) {
        code += `sum = sum + ${i}\n`;
      }
      code += "println(str(sum))";
      const { output } = exec(code);
      const expected = (49 * 50) / 2; // 0+1+...+49
      expect(output).toEqual([String(expected)]);
    });

    it("중첩 블록 스코핑", () => {
      const { output } = exec(
        `var x = 10
if true {
  var x = 20
  println(str(x))
}
println(str(x))`
      );
      expect(output).toEqual(["20", "10"]);
    });
  });

  describe("함수 호출 & 콜 스택", () => {
    it("함수 체인 호출", () => {
      const { output } = exec(
        `fn f1(x: i32) -> i32 { return x + 1 }
fn f2(x: i32) -> i32 { return f1(x) + 1 }
fn f3(x: i32) -> i32 { return f2(x) + 1 }
println(str(f3(10)))`
      );
      expect(output).toEqual(["13"]);
    });

    it("함수 깊은 재귀", () => {
      const { output } = exec(
        `fn fib(n: i32) -> i32 {
  if n <= 1 { return n }
  return fib(n - 1) + fib(n - 2)
}
println(str(fib(6)))`
      );
      expect(output).toEqual(["8"]); // fib(6) = 8
    });

    it("함수 다중 반환값 타입", () => {
      const { output } = exec(
        `fn getInt() -> i32 { return 42 }
fn getStr() -> string { return "hello" }
fn getBool() -> bool { return true }
println(str(getInt()))
println(getStr())
println(str(getBool()))`
      );
      expect(output).toEqual(["42", "hello", "true"]);
    });

    it("상호 재귀 (서로 호출)", () => {
      const { output } = exec(
        `fn isEven(n: i32) -> bool {
  if n == 0 { return true }
  return isOdd(n - 1)
}
fn isOdd(n: i32) -> bool {
  if n == 0 { return false }
  return isEven(n - 1)
}
println(str(isEven(4)))
println(str(isOdd(3)))`
      );
      expect(output).toEqual(["true", "true"]);
    });

    it("함수 로컬 변수 격리", () => {
      const { output } = exec(
        `fn modify(x: i32) -> i32 {
  var x = x * 2
  x = x + 10
  return x
}
var a = 5
println(str(modify(a)))
println(str(a))`
      );
      expect(output).toEqual(["20", "5"]);
    });
  });

  describe("복합 데이터 구조", () => {
    it("struct 필드 수정", () => {
      const { output } = exec(
        `struct Point { x: f64, y: f64 }
var p = Point { x: 1.0, y: 2.0 }
println(str(p.x))
println(str(p.y))`
      );
      expect(output).toEqual(["1", "2"]);
    });

    it("배열 요소 수정", () => {
      const { output } = exec(
        `var arr = [1, 2, 3]
arr[1] = 99
println(str(arr[0]))
println(str(arr[1]))
println(str(arr[2]))`
      );
      expect(output).toEqual(["1", "99", "3"]);
    });

    it("다중 배열 (배열의 배열)", () => {
      const { output } = exec(
        `var matrix = [[1, 2], [3, 4]]
println(str(length(matrix)))
println(str(length(matrix[0])))`
      );
      expect(output).toEqual(["2", "2"]);
    });
  });

  describe("제어흐름 복잡도", () => {
    it("삼중 if-else", () => {
      const { output } = exec(
        `var x = 10
if x < 5 {
  println("small")
} else if x < 15 {
  println("medium")
} else {
  println("large")
}`
      );
      expect(output).toEqual(["medium"]);
    });

    it("반복문 조기 종료 (break)", () => {
      const { output } = exec(
        `for i in [1, 2, 3, 4, 5] {
  if i == 3 { break }
  println(str(i))
}`
      );
      expect(output).toEqual(["1", "2"]);
    });

    it("반복문 건너뛰기 (continue)", () => {
      const { output } = exec(
        `for i in [1, 2, 3, 4, 5] {
  if i == 3 { continue }
  println(str(i))
}`
      );
      expect(output).toEqual(["1", "2", "4", "5"]);
    });

    it("while 루프 상태 변경", () => {
      const { output } = exec(
        `var i: i32 = 0
var sum: i32 = 0
while i < 5 {
  sum = sum + i
  i = i + 1
}
println(str(sum))`
      );
      expect(output).toEqual(["10"]); // 0+1+2+3+4
    });
  });

  describe("예외 & 에러 처리", () => {
    it("런타임 에러 캐치 - 0으로 나누기", () => {
      const { output, error } = exec("println(str(10 / 0))");
      expect(error).toBeDefined();
      // 에러 메시지는 구현에 따라 다를 수 있음
    });

    it("수행 제한 초과 (무한 루프 감지)", () => {
      const { output, error } = exec("while true { var x = 1 }");
      expect(error).toBeDefined();
      expect(error).toContain("limit");
    });

    it("배열 범위 초과 접근", () => {
      const { output, error } = exec(
        `var arr = [1, 2, 3]
println(str(arr[10]))`
      );
      // 범위 초과 시 에러 또는 undefined 반환 (구현 의존)
      expect(error !== null || output.length > 0).toBe(true);
    });
  });

  describe("타입 변환 & 문자열화", () => {
    it("모든 타입 str() 변환", () => {
      const { output } = exec(
        `println(str(42))
println(str(3.14))
println(str(true))
println(str(false))`
      );
      expect(output).toEqual(["42", "3.14", "true", "false"]);
    });

    it("복합 표현식 str() 변환", () => {
      const { output } = exec(
        `println(str(1 + 2 * 3))
println(str(10 > 5))
println(str(true && false))`
      );
      expect(output).toEqual(["7", "true", "false"]);
    });
  });

  describe("성능 & 확장성", () => {
    it("1000개 요소 배열", () => {
      let code = "var arr = [";
      for (let i = 0; i < 1000; i++) {
        code += (i > 0 ? ", " : "") + i;
      }
      code += "]\nprintln(str(length(arr)))";
      const { output } = exec(code);
      expect(output).toEqual(["1000"]);
    });

    it("깊은 재귀 (50단계)", () => {
      const { output } = exec(
        `fn countdown(n: i32) -> void {
  if n <= 0 {
    println("done")
  } else {
    countdown(n - 1)
  }
}
countdown(50)`
      );
      expect(output).toEqual(["done"]);
    });
  });
});

